import "./ListaDeTarefas.css";

function ListaDeTarefas({ tarefas }) {
  return (
    <div className="lt-cartao">
      <h2 className="lt-titulo">Lista de Tarefas</h2>

      {tarefas.length > 0 ? (
        <ul className="lt-lista">
          {tarefas.map((tarefa, indice) => (
            <li className="lt-item" key={indice}>
              {tarefa}
            </li>
          ))}
        </ul>
      ) : (
        <p className="lt-vazio">Nenhuma tarefa para mostrar.</p>
      )}
    </div>
  );
}

export default ListaDeTarefas;
